package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseJMigrationTest extends MigrationTestSupport {
 @Test @Tag("creative") void populatedPhaseIHistoryReceivesNoInventedConsentOrReceipt(){
  String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_j_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));
  Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("41").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES ('j-legacy@example.test','preserved-hash','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO profiles(user_id,username,display_name,is_profile_private) VALUES (?,'j_legacy','Historical',FALSE)",user);db.update("INSERT INTO policy_acceptances(user_id,policy_key,version,accepted_at) VALUES (?,'terms',1,'2026-01-01T00:00:00Z')",user);db.update("UPDATE user_preferences SET support_topics=ARRAY['anxiety'],onboarding_complete=TRUE,onboarding_status='LEGACY_UNKNOWN' WHERE user_id=?",user);
   var latest=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();latest.migrate();latest.validate();assertThat(db.queryForObject("SELECT count(*) FROM processing_authorizations",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM privacy_notice_receipts",Integer.class)).isZero();assertThat(db.queryForObject("SELECT review_status FROM policy_documents WHERE policy_key='terms' AND version=1",String.class)).isEqualTo("LEGACY_UNREVIEWED");assertThat(db.queryForObject("SELECT accepted_at='2026-01-01T00:00:00Z' FROM policy_acceptances WHERE user_id=?",Boolean.class,user)).isTrue();assertThat(db.queryForObject("SELECT is_profile_private FROM profiles WHERE user_id=?",Boolean.class,user)).isFalse();assertThat(db.queryForObject("SELECT support_topics[1] FROM user_preferences WHERE user_id=?",String.class,user)).isEqualTo("anxiety");assertThat(db.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user)).isEqualTo("preserved-hash");
  }finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
